function init(root = document) {
  const elements = [...(root.matches && root.matches('[data-pd]') ? [root] : []), ...root.querySelectorAll('[data-pd]')]
  return elements.map((element) => {
    if (controllers.has(element) && !controllers.get(element).dead) return controllers.get(element).api
    const name = element.dataset.pd.startsWith('Pd') ? element.dataset.pd : 'Pd' + element.dataset.pd
    let options = {}
    try { options = JSON.parse(element.dataset.options || '{}') } catch (_) { throw new Error('Invalid data-options JSON for ' + name) }
    return mount(element, name, options)
  })
}
function destroy(root = document) {
  const matches = [...live].filter((instance) => root === document || instance.element && (root === instance.element || root.contains(instance.element)) || root === instance.boundary)
  matches.forEach((instance) => instance.destroy())
}
global.PaylaterHTML = {
  init, destroy,
  get(element) { const instance = controllers.get(element); if (!instance || instance.dead) throw new Error('No active HTML controller on this element'); return instance.api },
  create(name, options = {}, contents = {}) { const host = document.createElement('div'); return mount(host, name.startsWith('Pd') ? name : 'Pd' + name, options, Object.fromEntries(Object.entries(contents).map(([key, value]) => [key, typeof value === 'function' ? value : () => [{ tag: 'native-content', original: value instanceof Node ? value : document.createTextNode(String(value)) }]]))) },
  part(name, options = {}, contents = {}, listeners = {}) { const values = Object.fromEntries(Object.entries(contents).map(([key, value]) => [key, typeof value === 'function' ? value : () => value])); return node(name.startsWith('Pd') ? name : 'Pd' + name, options, listeners, [], {}, values, { __nativeController: { definition: {} } }) },
  showDemo(id, host, options = {}) { if (!definitions['demo:' + id]) throw new Error('Unknown HTML demo: ' + id); destroy(host); return mount(host, 'demo:' + id, options) },
  getVisualAsset: visualAsset,
  componentNames: Object.keys(nativeContracts).filter((name) => definitions[name]).map((name) => name.slice(2)),
  flush,
  // Diagnostic hook used by the local parity runner; not an application API.
  diagnostics() { return { instances: live.size, activeDialogs: typeof openDialogs === 'undefined' ? document.querySelectorAll('[aria-modal="true"]').length : openDialogs.length } }
}

